const BRANCH = {"src/manual-review/services/conclude-manual-review-decision-service.spec.ts":"import { NotFoundException } from '@nestjs/common';\nimport { Test } from '@nestjs/testing';\nimport { getDataSourceToken } from '@nestjs/typeorm';\nimport { ConcludeManualReviewDecisionService } from './conclude-manual-review-decision-service';\nimport { RecordEventsProducer } from '../../kafka/record-events.producer';\nimport { ReviewAuditService } from '../../kafka/review-audit.service';\nimport { NotificationsOutboxService } from '../../outbox/notifications-outbox.service';\n\ndescribe('ConcludeManualReviewDecisionService', () => {\n  let service: ConcludeManualReviewDecisionService;\n  const manager = { findOne: jest.fn(), save: jest.fn() };\n  const queryRunner = {\n    manager,\n    connect: jest.fn(),\n    startTransaction: jest.fn(),\n    commitTransaction: jest.fn(),\n    rollbackTransaction: jest.fn(),\n    release: jest.fn(),\n  };\n  const repository = { update: jest.fn(), find: jest.fn() };\n  const dataSource = { createQueryRunner: () => queryRunner, getRepository: () => repository };\n  const producer = { publishDuplicateFound: jest.fn(), publishReviewConcluded: jest.fn() };\n  const audit = { recordDecision: jest.fn() };\n  const outbox = { notifyReviewConcluded: jest.fn() };\n\n  beforeEach(async () => {\n    jest.clearAllMocks();\n    const moduleRef = await Test.createTestingModule({\n      providers: [\n        ConcludeManualReviewDecisionService,\n        { provide: getDataSourceToken('legacy'), useValue: dataSource },\n        { provide: RecordEventsProducer, useValue: producer },\n        { provide: ReviewAuditService, useValue: audit },\n        { provide: NotificationsOutboxService, useValue: outbox },\n      ],\n    }).compile();\n    service = moduleRef.get(ConcludeManualReviewDecisionService);\n  });\n\n  it('approves a record and writes the notification to the outbox', async () => {\n    manager.findOne.mockResolvedValueOnce({ id: 7, guid: 'g-1', status: 'PENDING' }).mockResolvedValueOnce(null);\n    const record = await service.approve('g-1', 'officer-3');\n    expect(record.status).toBe('APPROVED');\n    expect(outbox.notifyReviewConcluded).toHaveBeenCalledWith('g-1', 7, manager);\n    expect(queryRunner.commitTransaction).toHaveBeenCalled();\n  });\n\n  it('throws NotFoundException for an unknown record', async () => {\n    manager.findOne.mockResolvedValueOnce(null);\n    await expect(service.approve('missing', 'officer-3')).rejects.toBeInstanceOf(NotFoundException);\n    expect(queryRunner.rollbackTransaction).toHaveBeenCalled();\n  });\n\n  it('publishes duplicate-found when another row is already approved', async () => {\n    manager.findOne.mockResolvedValueOnce({ id: 7, guid: 'g-1', status: 'PENDING' }).mockResolvedValueOnce({ id: 3, guid: 'g-1', status: 'APPROVED' });\n    await service.approve('g-1', 'officer-3');\n    expect(producer.publishDuplicateFound).toHaveBeenCalledWith('g-1', '3');\n  });\n\n  it('stores manual data on the approved row only', async () => {\n    manager.findOne.mockResolvedValueOnce({ id: 7, guid: 'g-1', status: 'PENDING' }).mockResolvedValueOnce(null);\n    await service.approve('g-1', 'officer-3', { nationality: 'NL' });\n    expect(repository.update).toHaveBeenCalledWith({ id: 7 }, { manualData: { nationality: 'NL' } });\n  });\n\n  it('publishes review-concluded after commit', async () => {\n    manager.findOne.mockResolvedValueOnce({ id: 7, guid: 'g-1', status: 'PENDING' }).mockResolvedValueOnce(null);\n    await service.approve('g-1', 'officer-3');\n    expect(producer.publishReviewConcluded).toHaveBeenCalledWith('g-1', 'APPROVED');\n  });\n});\n","src/manual-review/services/conclude-manual-review-decision-service.ts":"import { Injectable, NotFoundException } from '@nestjs/common';\nimport { InjectDataSource } from '@nestjs/typeorm';\nimport { DataSource } from 'typeorm';\nimport { UserRecord } from '../../user-records/entities/user-record.entity';\nimport { RecordEventsProducer } from '../../kafka/record-events.producer';\nimport { ReviewAuditService } from '../../kafka/review-audit.service';\nimport { NotificationsOutboxService } from '../../outbox/notifications-outbox.service';\n\n@Injectable()\nexport class ConcludeManualReviewDecisionService {\n  constructor(\n    @InjectDataSource('legacy') private readonly legacyDataSource: DataSource,\n    private readonly recordEventsProducer: RecordEventsProducer,\n    private readonly reviewAuditService: ReviewAuditService,\n    private readonly notificationsOutboxService: NotificationsOutboxService,\n  ) {}\n\n  async approve(guid: string, reviewerId: string, manualData?: Record<string, unknown>): Promise<UserRecord> {\n    const queryRunner = this.legacyDataSource.createQueryRunner();\n    await queryRunner.connect();\n    await queryRunner.startTransaction();\n    try {\n      const record = await queryRunner.manager.findOne(UserRecord, { where: { guid } });\n      if (!record) {\n        throw new NotFoundException(`No user record ${guid}`);\n      }\n      const duplicate = await queryRunner.manager.findOne(UserRecord, { where: { guid, status: 'APPROVED' } });\n      if (duplicate && duplicate.id !== record.id) {\n        await this.recordEventsProducer.publishDuplicateFound(guid, String(duplicate.id));\n      }\n      if (manualData) {\n        await this.setUserRecordManualReviewDataForRow(record.id, manualData);\n      }\n      record.status = 'APPROVED';\n      record.reviewerId = reviewerId;\n      await queryRunner.manager.save(record);\n      await this.notificationsOutboxService.notifyReviewConcluded(guid, record.id, queryRunner.manager);\n      await queryRunner.commitTransaction();\n      await this.reviewAuditService.recordDecision(guid, reviewerId, 'APPROVED');\n      await this.recordEventsProducer.publishReviewConcluded(guid, 'APPROVED');\n      return record;\n    } catch (error) {\n      await queryRunner.rollbackTransaction();\n      throw error;\n    } finally {\n      await queryRunner.release();\n    }\n  }\n\n  async reject(guid: string, reviewerId: string): Promise<void> {\n    await this.legacyDataSource.getRepository(UserRecord).update({ guid }, { status: 'REJECTED', reviewerId });\n    await this.reviewAuditService.recordDecision(guid, reviewerId, 'REJECTED');\n  }\n\n  async setUserRecordManualReviewData(guid: string, manualData: Record<string, unknown>): Promise<void> {\n    const rows = await this.legacyDataSource.getRepository(UserRecord).find({ where: { guid } });\n    for (const row of rows) {\n      await this.setUserRecordManualReviewDataForRow(row.id, manualData);\n    }\n  }\n\n  /** Manual data belongs to one record row, not to every row that shares the guid. */\n  async setUserRecordManualReviewDataForRow(recordId: number, manualData: Record<string, unknown>): Promise<void> {\n    await this.legacyDataSource.getRepository(UserRecord).update({ id: recordId }, { manualData });\n  }\n}\n"};
